function validate([source, pattern, targetIndices]) {
  const n = source.length;
  if (n < 1 || n > 3000) return 'source has 1 to 3000 letters.';
  if (pattern.length < 1 || pattern.length > n) return 'pattern has between 1 and n letters.';
  if (!/^[a-z]+$/.test(source) || !/^[a-z]+$/.test(pattern)) return 'source and pattern use only lowercase English letters.';
  if (targetIndices.length < 1 || targetIndices.length > n) return 'targetIndices holds between 1 and n indices.';
  for (let i = 0; i < targetIndices.length; i++) {
    if (targetIndices[i] < 0 || targetIndices[i] >= n) return 'Every target index is between 0 and n - 1.';
    if (i > 0 && targetIndices[i] <= targetIndices[i - 1]) return 'targetIndices must be strictly increasing (sorted, no repeats).';
  }
  let matched = 0;
  for (let i = 0; i < n && matched < pattern.length; i++) if (source[i] === pattern[matched]) matched++;
  if (matched < pattern.length) return 'pattern must be a subsequence of source.';
  return null;
}

