function maxRemovals(source, pattern, targetIndices) {
  const n = source.length;
  const m = pattern.length;
  const isTarget = new Array(n).fill(0);
  for (const index of targetIndices) {
    isTarget[index] = 1;
  }
  const dp = new Array(m + 1).fill(-Infinity);
  dp[0] = 0;
  for (let i = 0; i < n; i++) {
    for (let j = m; j >= 1; j--) {
      const skip = dp[j] + isTarget[i];
      const keep = source[i] === pattern[j - 1] ? dp[j - 1] : -Infinity;
      dp[j] = Math.max(skip, keep);
    }
    dp[0] += isTarget[i];
  }
  return dp[m];
}

