function maxRemovals(source, pattern, targetIndices) {
  // Try every set of target indices to delete; keep the largest set that still leaves pattern as a subsequence.
  let best = 0;
  for (let mask = 0; mask < (1 << targetIndices.length); mask++) {
    const removed = new Set(targetIndices.filter((_, bit) => mask & (1 << bit)));
    if (removed.size <= best) continue;
    let matched = 0;
    for (let i = 0; i < source.length && matched < pattern.length; i++) {
      if (!removed.has(i) && source[i] === pattern[matched]) matched++;
    }
    if (matched === pattern.length) best = removed.size;
  }
  return best;
}

