function generate(rand, size) {
  const n = size === 'large' ? 3000 : 1 + Math.floor(rand() * 10);
  // Large inputs use more letters, so the letters outside targetIndices are often too few to spell pattern alone.
  const alphabet = size === 'large' ? 4 + Math.floor(rand() * 3) : 1 + Math.floor(rand() * 3);
  const source = Array.from({ length: n }, () => 'abcdef'[Math.floor(rand() * alphabet)]).join('');
  // pattern keeps a random part of source, so it is always a subsequence; large ones stay near 300 letters.
  const keepChance = size === 'large' ? 0.075 + rand() * 0.035 : 0.2 + rand() * 0.8;
  let pattern = '';
  for (const letter of source) if (rand() < keepChance) pattern += letter;
  if (!pattern) pattern = source[Math.floor(rand() * n)];
  const targetChance = size === 'large' ? 0.45 + rand() * 0.2 : 0.2 + rand() * 0.8;
  const targetIndices = [];
  for (let i = 0; i < n; i++) if (rand() < targetChance) targetIndices.push(i);
  if (!targetIndices.length) targetIndices.push(Math.floor(rand() * n));
  // The app accepts at most 2,000 items per array.
  if (targetIndices.length > 2000) targetIndices.length = 2000;
  return [source, pattern, targetIndices];
}
